// ---------- monta a entrevista
function ivPickText(t,x){const s=pick(Array.isArray(t)?t:[t]);return ivFill(typeof s==="function"?s(x):s,x)}
function ivQuote(t){const p=t.split(/(?<=[.!?])\s/);let s=p[0];if(s.length<22&&p[1])s=s+" "+p[1];s=s.replace(/[.!]$/,"");return s.length>90?s.slice(0,88)+"…":s}
globalThis.makeInterview=function(type){const x=ivCtx(type);const bank=type==="pre"?IV_PRE:IV_POST;G.ivSeen=G.ivSeen||{};G.ivN=(G.ivN||0)+1;
  const cand=[];for(const q of bank){let w=0;try{w=q.w(x)}catch(e){w=0}if(!w)continue;const ago=G.ivN-(G.ivSeen[q.id]||-99);if(ago<5&&w<60)w*=.12;else if(ago<5)w*=.6;cand.push({q,s:w*(.75+rnd()*.5)})}
  cand.sort((a,b)=>b.s-a.s);const used={},qs=[];
  for(const c of cand){if(qs.length>=3)break;if(used[c.q.cat])continue;used[c.q.cat]=1;G.ivSeen[c.q.id]=G.ivN;const def=c.q;
    const j=jPick(def.j);const forced=def.qf&&def.qf(x);const qtxt=ivFill(forced||pick(def.q)(x),x);const groups=typeof def.a==="function"?def.a(x):def.a;
    const opts=groups.map(g=>{const t=ivPickText(g.t,x);return A(t,g.tone,g.eff,ivQuote(t))});for(let i=opts.length-1;i>0;i--){const k=Math.floor(rnd()*(i+1));[opts[i],opts[k]]=[opts[k],opts[i]]}
    qs.push(Q(j,qtxt,opts.slice(0,4)))}
  const I={type,qs,ans:[],i:0};G.interview=I;return I};
// manchetes com mais variedade (o resto do finishInterview segue o media.js)
(function(){const base=finishInterview;globalThis.finishInterview=function(){const I=G.interview;const art=base();try{if(!art||!I||!I.ans.length)return art;const sur=ME().n.split(" ").pop();
  const score=a=>({polemico:5,emocional:3,confiante:2,tecnico:1,humilde:1,evasivo:0}[a.a.tone]||0);const top=I.ans.slice().sort((p,q)=>score(q)-score(p))[0];const qt=top.a.quote;
  const HL={polemico:[`${sur} solta o verbo: "${qt}"`,`Polêmica no paddock: ${sur} diz "${qt}"`,`"${qt}": a frase de ${sur} que vai dar o que falar`,`${sur} não poupa ninguém: "${qt}"`],
    emocional:[`${sur}, emocionado: "${qt}"`,`"${qt}", diz um ${sur} tocado`,`O lado humano de ${sur}: "${qt}"`],confiante:[`${sur} avisa: "${qt}"`,`Confiança total: ${sur} diz "${qt}"`,`"${qt}", garante ${sur}`],
    tecnico:[`${sur} explica: "${qt}"`,`Na análise de ${sur}: "${qt}"`,`${sur} detalha o fim de semana: "${qt}"`],humilde:[`${sur}: "${qt}"`,`Com os pés no chão, ${sur} diz "${qt}"`,`"${qt}", reconhece ${sur}`],evasivo:[`${sur} desconversa e evita polêmica`,`${sur} prefere não se comprometer`,`Poucas palavras de ${sur} na ${I.type==="pre"?"coletiva":"zona mista"}`]};
  if(rnd()<.6){art.headline=pick(HL[top.a.tone]||HL.humilde)}}catch(e){}return art}})();
